// Package models is the catalogue of UniFi AP models an OpenWrt AP can be
// adopted as (catalog.json, generated by tools/gen-models.py from unifi-emu;
// see NOTICE), the profile each model reports, and a suggestion of the
// closest model for a given AP.
package models

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"

	"github.com/antoniocosta/unifi-openwrt/internal/inform"
)

//go:embed catalog.json
var catalogJSON []byte

type Radio struct {
	Band  string `json:"band"` // ng, na, 6e
	NSS   int    `json:"nss"`
	MinTx int    `json:"min_tx"`
	MaxTx int    `json:"max_tx"`
}

type Model struct {
	Code    string  `json:"model"`
	Display string  `json:"display"`
	Version string  `json:"version"`
	Gen     int     `json:"gen"` // Wi-Fi generation (4, 5, 6, 7); 0 = unknown
	Radios  []Radio `json:"radios"`
}

var catalog = func() map[string]Model {
	var c struct {
		Models []Model `json:"models"`
	}
	if err := json.Unmarshal(catalogJSON, &c); err != nil {
		panic(err)
	}
	m := map[string]Model{}
	for _, x := range c.Models {
		m[x.Code] = x
	}
	return m
}()

// All lists the catalogue, sorted by code.
func All() []Model {
	var out []Model
	for _, m := range catalog {
		out = append(out, m)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Code < out[j].Code })
	return out
}

func Lookup(code string) (Model, bool) {
	m, ok := catalog[strings.ToUpper(code)]
	return m, ok
}

func (m Model) Bands() string {
	var b []string
	for _, r := range m.Radios {
		b = append(b, r.Band)
	}
	return strings.Join(b, "+")
}

// Profile is what the AP reports when adopted as model m. The capability
// words (fw_caps, wifi_caps, radio caps) are the measured UAP-AC-Pro ones
// (the only full set we have); identity, firmware version and radios come
// from the model. The translator still clamps what the hardware lacks.
func Profile(m Model) inform.Profile {
	base := inform.U7PG2
	if m.Code == base.Model {
		return base // the measured AC-Pro profile, exactly
	}
	p := inform.Profile{Model: m.Code, Display: m.Display, Version: m.Version,
		FWCaps: base.FWCaps, FW2Caps: base.FW2Caps, WifiCaps: base.WifiCaps, WifiCaps2: base.WifiCaps2,
		Radios: map[string]inform.RadioProfile{}}
	if p.Version == "" {
		p.Version = base.Version
	}
	for _, r := range m.Radios {
		rp := base.Radios[r.Band]
		if r.Band == "6e" {
			rp = base.Radios["na"]
		}
		rp.NSS, rp.MinTx, rp.MaxTx = r.NSS, r.MinTx, r.MaxTx
		rp.Is11ac = r.Band != "ng" && m.Gen >= 5
		p.Radios[r.Band] = rp
	}
	return p
}

// AP describes an OpenWrt AP for Suggest.
type AP struct {
	Bands []string // ng, na, 6e
	NSS   int      // most spatial streams of any radio
	Gen   int      // best Wi-Fi generation (4 n, 5 ac, 6 ax, 7 be)
}

// Suggest ranks the catalogue for ap: same bands first, then the same Wi-Fi
// generation, then the same stream count. Models of unknown generation are
// left out.
func Suggest(ap AP) []Model {
	want := strings.Join(sortedBands(ap.Bands), "+")
	type scored struct {
		m Model
		s int
	}
	var ss []scored
	for _, m := range catalog {
		if m.Gen == 0 {
			continue
		}
		s := 0
		if strings.Join(sortedBands(bandsOf(m)), "+") == want {
			s += 100
		}
		s -= 10 * abs(m.Gen-ap.Gen)
		nss := 0
		for _, r := range m.Radios {
			nss = max(nss, r.NSS)
		}
		s -= 3 * abs(nss-ap.NSS)
		if m.Code == inform.U7PG2.Model {
			s++ // the only model with fully measured capability words
		}
		ss = append(ss, scored{m, s})
	}
	sort.Slice(ss, func(i, j int) bool {
		if ss[i].s != ss[j].s {
			return ss[i].s > ss[j].s
		}
		return ss[i].m.Code < ss[j].m.Code
	})
	var out []Model
	for _, x := range ss {
		out = append(out, x.m)
	}
	return out
}

func bandsOf(m Model) []string {
	var b []string
	for _, r := range m.Radios {
		b = append(b, r.Band)
	}
	return b
}

func sortedBands(b []string) []string {
	c := append([]string{}, b...)
	sort.Strings(c)
	return c
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func (m Model) String() string {
	return fmt.Sprintf("%-8s %-28s Wi-Fi %d  %s", m.Code, m.Display, m.Gen, m.Bands())
}
